#include "control_service.h"
#include <string.h>
ps_result cs_init(cs_service *s,const ps_io *io,const ap_identity *id,uint64_t now){ps_result r;if(!s||s->initialized||!ps_io_valid(io)||!ap_identity_valid(id))return PS_INVALID;s->initialized=1;s->io=*io;r=rj_boot(io,&s->journal);if(r!=PS_OK)s->durable_block=1;if(ap_init(&s->policy,id,now)!=AP_OK){s->durable_block=1;return PS_INVALID;}return r;}
ap_refusal cs_request(cs_service *s,ap_desired desired,uint64_t now){ap_refusal r;uint64_t token=0;ap_status state;if(!s||!s->initialized)return AP_NOT_INITIALIZED;if(desired==AP_OFF)return ap_request(&s->policy,desired,now);if(s->durable_block||s->journal.unresolved)return AP_RESTORATION_OUTSTANDING;r=ap_request(&s->policy,desired,now);if(r!=AP_OK)return r;ap_query(&s->policy,&state);if(state.action!=AP_ACTION_ATTACH)return AP_OK;if(rj_intent(&s->io,&s->journal,&s->policy.target,&token)!=PS_OK){s->durable_block=1;(void)ap_report_fault(&s->policy);return AP_RUNTIME_FAULT;}return AP_OK;}
ap_refusal cs_tick(cs_service *s,uint64_t now){return !s||!s->initialized?AP_NOT_INITIALIZED:ap_tick(&s->policy,now);}
int cs_query(const cs_service *s,cs_status *out){if(!s||!s->initialized||!out)return 0;memset(out,0,sizeof(*out));if(ap_query(&s->policy,&out->policy)!=AP_OK)return 0;out->durable_block=s->durable_block;out->recovery_required=s->journal.unresolved;out->incarnation=s->journal.incarnation;out->recovery_incarnation=s->journal.attach_incarnation;out->recovery_token=s->journal.token;out->recovery_identity=s->journal.identity;/* Do not expose an attach permission until durable admission is established. */if(s->durable_block&&out->policy.action==AP_ACTION_ATTACH)out->policy.action=AP_ACTION_NONE;return 1;}
ap_refusal cs_ack_attach(cs_service *s,const ap_identity *id,uint64_t incarnation,uint64_t token,ap_ack ack,uint64_t now){ap_status status;if(!s||!s->initialized)return AP_NOT_INITIALIZED;if(s->durable_block||!s->journal.unresolved||incarnation!=s->journal.attach_incarnation||incarnation!=s->journal.incarnation||token!=s->journal.token||!ps_identity_equal(id,&s->journal.identity))return AP_STALE_TOKEN;ap_query(&s->policy,&status);return ap_ack_attach(&s->policy,id,status.token,ack,now);}
ps_result cs_ack_restore(cs_service *s,const ap_identity *id,uint64_t incarnation,uint64_t token,ap_ack ack){ps_result r;ap_status status;if(!s||!s->initialized)return PS_INVALID;ap_query(&s->policy,&status);/* A restore cannot clear an active or pending original policy. OFF first. */if(status.observed==AP_ACTIVE||status.observed==AP_PENDING_ATTACH)return PS_INVALID;r=rj_restored(&s->io,&s->journal,id,incarnation,token,ack);if(r!=PS_OK)return r;if(status.restoration_outstanding&&ap_ack_restore(&s->policy,id,status.token,AP_ACK_SUCCESS)!=AP_OK){s->durable_block=1;return PS_INVALID;}/* A prior IO failure needs a fresh service/reboot, not an ACK unlock. */return PS_OK;}
#ifdef HELIX_CONTROL_TEST
ap_refusal cs_test_qualify(cs_service *s,const ap_evidence *e,uint64_t now){return !s||!s->initialized?AP_NOT_INITIALIZED:ap_update(&s->policy,e,now);}
#endif
